(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.05-t*0.5)*5 + Math.cos(y*0.04+t*0.6)*4;
  const w2y = Math.cos(y*0.05+t*0.45)*5 + Math.sin(x*0.045-t*0.55)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 1.05],
    [200+Math.sin(t*0.25+6)*110, 220+Math.cos(t*0.45+3)*60, 0.075, 2.4, 0.95],
    [280+Math.cos(t*0.65+1)*90, 30+Math.sin(t*0.35+5)*70, 0.095, 1.6, 1.15]
  ];
  let aS = 0, iS = 0, dS = 0, wSum = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    dS += Math.sin(d*f*0.4 - t*sp*0.3 + 3.0) * w * 0.5;
    wSum += w;
  }
  const act = aS/wSum, inh = iS/wSum, diff = dS/wSum;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*0.3)*Math.sin(sy*0.06-t*0.4)*0.3;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.03+ang*5-t*0.8)*0.2;
  const spiral = spiral1 + spiral2;
  const fd = Math.sin(sx*0.3+t)*Math.cos(sy*0.3-t*0.7)*Math.sin((sx+sy)*0.15+t*1.5)*0.3;
  const raw = act - inh*0.7 + bg*0.3 + spiral + diff*0.4 + fd*0.15;
  const reaction = Math.tanh(raw*2.2);
  const reaction2 = Math.tanh((act*0.5 + diff - bg*0.5)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = reaction*0.55 + cell*0.15 + reaction2*0.3;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[12,35,75],[20,70,105],[30,120,130],[60,165,140],
    [140,195,120],[210,195,85],[235,165,65],[220,110,60],
    [185,65,55],[130,40,55],[70,25,55],[30,15,50],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const intensity = Math.abs(reaction);
  const lum = 0.75 + intensity*0.15 + Math.sin(reaction*Math.PI)*0.1;
  const edgeGlow = intensity > 0.65 ? 1.0 + (intensity-0.65)*0.6 : 1.0;
  const shift = reaction2 * 0.08;
  return [
    Math.min(255, Math.max(0, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(lum*edgeGlow) + shift*30)|0)),
    Math.min(255, Math.max(0, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*(lum*edgeGlow) + shift*10)|0)),
    Math.min(255, Math.max(0, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(lum*edgeGlow) - shift*20)|0))
  ];
}
